/**
 * @method
 * @name txb_IsurCd_onblur
 * @description txb_IsurCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onblur = function() {
    try {
        if (txb_IsurCd.getValue() === "") {
            txb_CoNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.txb_IsurCd_onblur" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onchange
 * @description txb_IsurCd 값 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onchange = function (info) {
    try {

        if(info.newValue.length === 0) txb_CoNm.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.txb_IsurCd_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (!await scwin.validate()) {
        return;
    }

    let reqMap = {
        // 회사코드
        isurCd: txb_IsurCd.getValue(),
        // 청구접수시작일
        billSubmitStartDate: edt_SDate.getValue(),
        // 청구접수종료일
        billSubmitEndDate: edt_EDate.getValue()
    };

    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/lstproc/stock/legacy-prelisting-ksq/select-list",
        method: "get",
        target: "dlt_listPrelisting=body",
        gridview: "grd_Prelisting",
        isProcessMsg: true
    };

    $c.sbm.executeDynamic($p, sbmOptions, reqMap);
};

/**
 * @method
 * @name sbm_selectList_submitdone
 * @description sbm_selectList 통신 응답 후처리
 * @returns {void}
 * @hidden N
 */
scwin.sbm_selectList_submitdone = function() {
    panel_page.setValue(grd_Prelisting.getRowCount());
}

/**
 * @method
 * @name procCheckSync
 * @description 처리 가능 여부를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procCheckSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Proc_Check",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Proc_Check=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let vCtnt = "";
    if (dts_Proc_Check.getRowCount() > 0) {
        for (let i = 1; i <= dts_Proc_Check.getRowCount(); i++) {
            vCtnt += "\r\n";
            let vNm = "";
            if (dts_Proc_Check.getCellData(i, "EXAMPRN_NM") === "") {
                vNm += "심사자";
            }
            if (dts_Proc_Check.getCellData(i, "ACPT_COMPLT") === "" || dts_Proc_Check.getCellData(i, "ACPT_COMPLT") === "N") {
                if (vNm === "") {
                    vNm += "접수자";
                } else {
                    vNm += ",접수자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "REVW_COMPLT") === "" || dts_Proc_Check.getCellData(i, "REVW_COMPLT") === "N") {
                if (vNm === "") {
                    vNm += "검토자";
                } else {
                    vNm += ",검토자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "COMITE_COMPLT") === "") {
                if (vNm === "") {
                    vNm += "위원회완료자";
                } else {
                    vNm += ",위원회완료자";
                }
            }
            vCtnt += "상장완료후 " + dts_Proc_Check.getCellData(i, "COM_NM") + "가 " + vNm + "가 입력이 누락되었습니다, 입력해 주시기 바랍니다.";
            vCtnt += "\r\n";
        }
        $c.win.alert(vCtnt);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name validate
 * @description 입력값 유효성을 검증한다.
 * @returns {Promise<Boolean>} 판정 결과
 * @hidden N
 */
scwin.validate = async function() {
    if ((edt_SDate.getValue() === "") || (edt_EDate.getValue() === "")) {
        await $c.win.alert(scwin.MSG_CND_DTE_REQ);
        return;
    }
    if (edt_SDate.getValue() > edt_EDate.getValue()) {
        await $c.win.alert(scwin.MSG_CND_DTE_BIG);
        return;
    }

    return true;
};

/**
 * @method
 * @name getParDtl
 * @description 상세화면
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getParDtl = function() { // 상세화면열기
    let cRow = dlt_listPrelisting.getRowPosition();

    let arrPar = [];
    arrPar[0] = dlt_listPrelisting.getCellData(cRow, "isurCd");
    arrPar[1] = dlt_listPrelisting.getCellData(cRow, "bzProcsNo");
    arrPar[2] = dlt_listPrelisting.getCellData(cRow, "comNm");

    return arrPar;
}

/**
 * @method
 * @name getParIsur
 * @description 부모 화면(팝업 호출원)으로 돌려줄 파라미터 배열을 만든다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션, 발행기관 목록팝업
    arrPar[0] = txb_IsurCd; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_CoNm; // 명칭값을 포함할 컨트롤
    arrPar[2] = "KSQ_EXEM"; // 코스닥예비심사

    return arrPar;
};

/**
 * @method
 * @name setParIsur
 * @description 팝업이 돌려준 파라미터 배열을 화면 입력값에 반영한다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    txb_IsurCd.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_CoNm.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};

/**
 * @method
 * @name setParDtl
 * @description 팝업이 돌려준 파라미터 배열을 화면 입력값에 반영한다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {void}
 * @hidden N
 */
scwin.setParDtl = function(arrPar) {
    scwin.listSync();
};

/**
 * @method
 * @name openDtl
 * @description 상세 화면 팝업을 연다.
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDtl = async function(row) {
    if ((row <= dlt_listPrelisting.getRowCount()) && (dlt_listPrelisting.getRowCount() > 0)) {

        const opts = {
            id: "ULDSTF05004",
            popupName: "예비심사청구상세",
            width: 1630,
            height: 1021,
            frameModal: "top",
        };

        const params = {
            "arrPar" : scwin.getParDtl() 
        };
        await $c.win.openPopup("/ui/lst/lstprocold/ULDSTF05004.xml", opts, params);
    }
};

/**
 * @method
 * @name openInvRst
 * @description 투자심사 결과 팝업을 연다.
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInvRst = async function(row) {
    if ((row <= dlt_listPrelisting.getRowCount()) && (dlt_listPrelisting.getRowCount() > 0)) {
        const opts = {
            id: "ULDSTF05010",
            popupName: "위원회결과",
            width: 910,
            height: 975,
            frameModal: "top",
        };

        const params = {
            "arrPar" : scwin.getParDtl() 
        };
        await $c.win.openPopup("/ui/lst/lstprocold/ULDSTF05010.xml", opts, params);
    }
};

/**
 * @method
 * @name openPubofr
 * @description 공모 정보 팝업을 연다.
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPubofr = async function(row) {
    if ((row <= dlt_listPrelisting.getRowCount()) && (dlt_listPrelisting.getRowCount() > 0)) {
        const opts = {
            id: "ULDSTF05009",
            popupName: "공모",
            width: 1290,
            height: 1100,
            frameModal: "top",
        };

        const params = {
            "arrPar" : scwin.getParDtl() 
        };
        await $c.win.openPopup("/ui/lst/lstprocold/ULDSTF05009.xml", opts, params);
    }
};

/**
 * @method
 * @Method
 * @name scwin.btn_CoCdSearch_onclic
 * @description :법인검색팝업호출
 * @returns {void}
 * @hidden N
 */
scwin.popFindExamCorp = async function(val) {
    let url = "/ui/lst/common/ULDSTF05011.xml";
    let popTitle = "법인 선택";

    const opts = {
        id: "ULDSTF05011",
        popupName: popTitle,
        width: 500,
        height: 700,
        frameModal: "top",
    };

    const popupData = {strTpCd: "KSQ_EXEM"};
    const res = await $c.win.openPopup(url, opts, popupData);

    txb_IsurCd.setValue(res.isurCd) ; // 법인코드
    txb_CoNm.setValue(res.comNm) ; // 법인명

};

/**
 * @method
 * @name submitDd_displayFormatter
 * @description submitDd 표시 포매터
 * @param {*} data 셀 값(원본 데이터)
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.submitDd_displayFormatter = function (data) {
    return $c.date.formatDate(data, "-");
};
